-- Migration: Year 2 - Hematology Pathology MCQs Part 2 (41-80)
-- Date: 2026-04-24

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Hematology Pathology', 'hematology-pathology', 3, 2, 61)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES

    -- MACROCYTIC / MEGALOBLASTIC ANEMIAS (41-58)
    (v_topic_id, 'Vitamin B12 deficiency causes megaloblastic anemia. What is the most common cause of B12 deficiency in developed countries?', '["Strict vegan diet", "Pernicious anemia (autoimmune destruction of gastric parietal cells eliminating intrinsic factor)", "Crohn disease of the terminal ileum", "Metformin use"]', 1, 'Pernicious anemia is the #1 cause. Anti-parietal cell antibodies destroy gastric parietal cells; anti-intrinsic factor antibodies block IF function. Without IF, B12 cannot bind the cubilin receptor in the terminal ileum.'),
    (v_topic_id, 'In pernicious anemia, anti-intrinsic factor (anti-IF) antibodies have two subtypes. Type I (blocking antibodies) prevent?', '["IF from reaching the terminal ileum", "IF from binding B12 in the stomach", "B12 from binding to transcobalamin", "Parietal cell acid secretion"]', 1, 'Type I anti-IF antibodies (most specific) block the B12-binding site of IF, preventing the IF-B12 complex from forming. Type II antibodies prevent the IF-B12 complex from binding the ileal cubilin receptor.'),
    (v_topic_id, 'Which neurological syndrome is uniquely associated with B12 deficiency but NOT folate deficiency?', '["Peripheral neuropathy only", "Subacute combined degeneration of the spinal cord (dorsal columns + lateral corticospinal tracts)", "Wernicke encephalopathy", "Cerebellar ataxia"]', 1, 'B12 is required for methylmalonyl-CoA mutase. Deficiency causes MMA accumulation and incorporation of abnormal fatty acids into myelin. Demyelinates dorsal columns (loss of vibration/proprioception) and lateral corticospinal tracts (UMN signs).'),
    (v_topic_id, 'Why is it dangerous to treat a patient with combined B12 and folate deficiency with folate ALONE?', '["Folate worsens B12 absorption", "Folate corrects the anemia but allows neurological damage from B12 deficiency to progress undetected", "Folate increases homocysteine levels", "Folate causes rebound iron deficiency"]', 1, 'Folate corrects the hematological defect (megaloblastic anemia) but has NO effect on the neurological manifestations of B12 deficiency. The patient appears better but continues to develop subacute combined degeneration.'),
    (v_topic_id, 'Which two metabolites are elevated in B12 deficiency, and which one is also elevated in FOLATE deficiency?', '["MMA and homocysteine elevated in B12 deficiency; MMA also elevated in folate deficiency", "MMA and homocysteine elevated in B12 deficiency; only homocysteine elevated in folate deficiency", "Only homocysteine elevated in both; MMA normal in folate deficiency", "MMA elevated in both; homocysteine normal in folate deficiency"]', 1, 'In B12 deficiency: both MMA (methylmalonyl-CoA mutase requires B12) and homocysteine are elevated. In folate deficiency: only homocysteine is elevated (MMA is normal because MMA metabolism does not require folate). This distinction is diagnostically critical.'),
    (v_topic_id, 'Which population is at highest risk for folate deficiency anemia?', '["Elderly men on proton pump inhibitors", "Pregnant women, alcoholics, and patients on methotrexate or phenytoin", "Strict vegans over age 50", "Patients with Crohn disease of the terminal ileum"]', 1, 'Folate demands are highest in pregnancy (fetal cell division). Alcohol impairs folate absorption and metabolism. MTX inhibits DHFR (blocks THF formation). Phenytoin impairs folate absorption. The body stores only 3-4 months of folate (vs. 3-5 years for B12).'),
    (v_topic_id, 'Folate deficiency anemia is caused by impaired DNA synthesis. Which specific biochemical step requires folate (as tetrahydrofolate, THF)?', '["Conversion of methylmalonyl-CoA to succinyl-CoA", "Transfer of one-carbon units for thymidylate (dTMP) synthesis and purine synthesis", "Synthesis of intrinsic factor", "Hydroxylation of vitamin D"]', 1, 'THF carries one-carbon units required for: (1) converting dUMP to dTMP (thymidylate synthase) and (2) de novo purine synthesis. Without THF, DNA synthesis halts; cells grow but cannot divide, creating giant macro-ovalocytes.'),
    (v_topic_id, 'Methotrexate causes megaloblastic anemia by inhibiting which enzyme?', '["Thymidylate synthase", "Dihydrofolate reductase (DHFR), blocking conversion of DHF to THF", "Methylmalonyl-CoA mutase", "ALA synthase"]', 1, 'MTX inhibits DHFR. DHF cannot be converted to THF. Without THF, one-carbon transfers for dTMP and purine synthesis are blocked, halting DNA synthesis. Leucovorin (folinic acid = pre-formed THF) is used to rescue normal cells from MTX toxicity.'),
    (v_topic_id, 'The Schilling test is used to diagnose pernicious anemia. Which result pattern confirms pernicious anemia?', '["Stage 1 normal, Stage 2 abnormal (adding IF worsens absorption)", "Stage 1 abnormal (low urinary B12 excretion without IF), Stage 2 normalized (adding IF corrects absorption)", "Both Stage 1 and Stage 2 abnormal (terminal ileum disease)", "Stage 1 normal, Stage 2 normal"]', 1, 'In pernicious anemia: Stage 1 (oral B12 alone) is abnormal (low urinary excretion). Stage 2 (oral B12 + IF) normalizes excretion, confirming IF is the missing factor. If Stage 2 remains abnormal, the terminal ileum is the problem.'),
    (v_topic_id, 'A 68-year-old woman has Hgb 8, MCV 115, hypersegmented neutrophils, and tingling in her feet with impaired vibration sense. Serum B12 is low, serum MMA is elevated. Diagnosis and treatment?', '["Folate deficiency; treat with oral folate", "Pernicious anemia with subacute combined degeneration; treat with intramuscular B12 (cyanocobalamin)", "Iron deficiency anemia; treat with oral iron", "B12 deficiency from Crohn disease; treat with oral B12"]', 1, 'Classic pernicious anemia: elderly woman + macrocytic anemia + neurological findings + low B12 + elevated MMA. IM B12 is given because oral B12 requires IF for absorption (which she lacks). Large oral doses can also work via passive diffusion.'),
    (v_topic_id, 'Which gastric finding is associated with pernicious anemia on endoscopy/biopsy?', '["Helicobacter pylori gastritis only", "Autoimmune (Type A) atrophic gastritis: inflammation of the fundus/body with loss of parietal cells and chief cells, achlorhydria, and elevated gastrin", "Hypertrophic gastropathy (Menetrier disease)", "Normal gastric mucosa"]', 1, 'Type A autoimmune gastritis targets the fundus/body (where parietal cells live). Loss of parietal cells = loss of HCl (achlorhydria) + loss of intrinsic factor. G-cell hyperplasia in the antrum → hypergastrinemia. Increases risk of gastric carcinoid tumors.'),
    (v_topic_id, 'A patient with pernicious anemia has an elevated serum gastrin level. What is the most likely explanation?', '["The anti-parietal cell antibodies stimulate gastrin secretion", "Achlorhydria (from loss of parietal cells) removes negative feedback on antral G-cells, causing hypergastrinemia", "Gastrin is produced by parietal cells", "Intrinsic factor normally suppresses gastrin"]', 1, 'Normally, gastric acid (HCl) provides negative feedback to antral G-cells (suppressing gastrin). With achlorhydria, this feedback is lost, so G-cells continuously secrete gastrin. This chronic hypergastrinemia can drive gastric carcinoid tumor formation (ECL cell stimulation).'),
    (v_topic_id, 'Neural tube defects (spina bifida, anencephaly) are prevented by periconceptional supplementation of which vitamin?', '["Vitamin B12", "Folate (folic acid)", "Vitamin D", "Vitamin B6 (pyridoxine)"]', 1, 'Folate is critical for neural tube closure, which occurs at day 28 of gestation (before most women know they are pregnant). Folate supplementation must begin before conception. Most countries mandate folate fortification of grain products.'),
    (v_topic_id, 'Diamond-Blackfan anemia is a congenital macrocytic anemia characterized by?', '["Absent megakaryocytes with normal RBC precursors", "Pure red cell aplasia (absent erythroid precursors in marrow) with elevated fetal hemoglobin, associated with triphalangeal thumbs", "Pancytopenia from bone marrow failure", "Elevated B12 with megaloblastic changes"]', 1, 'Diamond-Blackfan: congenital pure red cell aplasia (aplasia of erythroid lineage only), macrocytic anemia, elevated HbF, elevated erythropoietin, and physical anomalies (triphalangeal thumbs, short stature). Caused by ribosomal protein gene mutations.'),
    (v_topic_id, 'Orotic aciduria is a rare cause of megaloblastic anemia. What is its unique distinguishing feature from B12 and folate deficiency?', '["Elevated serum B12", "Elevated MMA", "Orotic acid in urine WITHOUT hyperammonemia (ruling out urea cycle defects), caused by UMP synthase deficiency", "Normal MCV"]', 2, 'UMP synthase deficiency blocks pyrimidine synthesis, causing orotic acid accumulation. Megaloblastic anemia results because pyrimidines are needed for DNA synthesis. Importantly, no hyperammonemia (unlike ornithine transcarbamylase deficiency, which also elevates orotic acid but causes severe hyperammonemia).'),

    -- HEREDITARY SPHEROCYTOSIS (55-62)
    (v_topic_id, 'Hereditary spherocytosis is caused by mutations in RBC membrane skeletal proteins. Which protein defect is most commonly responsible?', '["Hemoglobin beta-chain mutation", "Spectrin or ankyrin deficiency (disrupting the spectrin-ankyrin-band 3 vertical linkage)", "G6PD enzyme deficiency", "Pyruvate kinase deficiency"]', 1, 'HS is caused by defects in vertical linkage proteins (ankyrin, spectrin, band 3, protein 4.2). These anchor the lipid bilayer to the cytoskeleton. Loss of this anchor leads to progressive membrane vesiculation and spherocyte formation.'),
    (v_topic_id, 'In hereditary spherocytosis, why are spherocytes preferentially destroyed in the spleen?', '["The spleen produces antibodies against spherocytes", "Spherocytes have reduced membrane deformability and cannot squeeze through the narrow splenic sinusoidal slits, leading to macrophage engulfment", "Spherocytes activate complement in the spleen", "The spleen filters spherocytes due to their abnormal hemoglobin"]', 1, 'Normal biconcave RBCs deform to pass through 2-3 micron splenic sinusoidal slits. Spherocytes (rigid, inflexible) cannot deform and are trapped and phagocytosed by splenic macrophages. Splenectomy cures the hemolysis.'),
    (v_topic_id, 'The diagnostic test of choice for hereditary spherocytosis is?', '["Direct Coombs test (DAT)", "Osmotic fragility test or EMA (eosin-5-maleimide) binding test", "Hemoglobin electrophoresis", "Serum ferritin"]', 1, 'EMA binding test is now preferred (measures band 3 and Rh proteins on RBC surface; reduced in HS). Classic teaching: osmotic fragility test (spherocytes lyse at higher salt concentrations). Direct Coombs is NEGATIVE, distinguishing HS from warm AIHA.'),
    (v_topic_id, 'A patient with hereditary spherocytosis suddenly develops a severe drop in hemoglobin after a flu-like illness. Reticulocyte count is nearly zero. Diagnosis?', '["Hyperhemolytic crisis", "Aplastic crisis from Parvovirus B19 infecting erythroid precursors", "Sequestration crisis", "Iron deficiency superimposed on HS"]', 1, 'Parvovirus B19 infects and kills pronormoblasts (erythroid precursors) in bone marrow. In patients with compensated hemolytic anemia (who rely on 3x normal marrow output), loss of erythroid production causes a sudden, severe aplastic crisis.'),
    (v_topic_id, 'Patients with hereditary spherocytosis are at risk for which type of gallstones?', '["Cholesterol gallstones", "Pigment (bilirubin) gallstones from chronic hemolysis", "Mixed gallstones", "Calcium oxalate stones"]', 1, 'Chronic hemolysis releases large amounts of heme, which is converted to unconjugated bilirubin. This is taken up by the liver and excreted as conjugated bilirubin in bile. High bile bilirubin concentration leads to calcium bilirubinate (pigment) stone formation.'),
    (v_topic_id, 'Splenectomy cures the hemolysis in hereditary spherocytosis. What characteristic finding appears on blood smear AFTER splenectomy?', '["Schistocytes", "Howell-Jolly bodies (nuclear remnants normally removed by spleen), increased spherocytes and target cells", "Ring sideroblasts", "Hypersegmented neutrophils"]', 1, 'After splenectomy, the blood smear shows: Howell-Jolly bodies (DNA remnants), target cells, acanthocytes, and MORE spherocytes (since the spleen is no longer removing them). However, hemolysis stops because the site of destruction is removed.'),
    (v_topic_id, 'Which vaccine is critically important to give before splenectomy for hereditary spherocytosis?', '["MMR and varicella", "Encapsulated bacteria vaccines: Pneumococcal, Meningococcal, and H. influenzae type b (Hib)", "Hepatitis B only", "Influenza only"]', 1, 'The spleen is critical for opsonizing encapsulated bacteria (S. pneumoniae, N. meningitidis, H. influenzae type b). Post-splenectomy patients have OPSI (overwhelming post-splenectomy infection) risk. Vaccinate against all three encapsulated organisms at least 2 weeks before elective splenectomy.'),
    (v_topic_id, 'Pyruvate kinase (PK) deficiency is a hemolytic anemia affecting RBC energy. What is the mechanism?', '["PK deficiency depletes ATP, causing RBC membrane Na/K pump failure, osmotic swelling, and hemolysis", "PK deficiency prevents heme synthesis", "PK deficiency causes Heinz body formation", "PK deficiency prevents iron incorporation"]', 0, 'RBCs rely exclusively on anaerobic glycolysis for ATP (no mitochondria). PK catalyzes the final ATP-generating step. PK deficiency depletes RBC ATP, impairing the Na/K-ATPase, causing cellular swelling and hemolysis. Morphology: echinocytes (burr cells).'),

    -- G6PD DEFICIENCY (63-70)
    (v_topic_id, 'G6PD deficiency is the most common hereditary enzyme deficiency. What is the inheritance pattern?', '["Autosomal recessive", "Autosomal dominant", "X-linked recessive (males predominantly affected)", "X-linked dominant"]', 2, 'G6PD is on the X chromosome. Males (XY) are affected if they inherit the defective allele. Females are usually carriers (mildly symptomatic) unless homozygous. Most affected populations: African, Mediterranean, and Middle Eastern men.'),
    (v_topic_id, 'G6PD is the first enzyme of the pentose phosphate pathway. Its role in RBC protection is?', '["Generating ATP for the Na/K pump", "Generating NADPH, which maintains glutathione in its reduced (active) form to neutralize oxidative stress", "Synthesizing heme groups", "Breaking down methemoglobin"]', 1, 'G6PD generates NADPH via the hexose monophosphate shunt. NADPH reduces oxidized glutathione (GSSG) back to GSH. Reduced glutathione (GSH) neutralizes H2O2 and other ROS. Without G6PD, oxidative stress denatures hemoglobin into Heinz bodies.'),
    (v_topic_id, 'What are Heinz bodies, and which stain is used to visualize them?', '["Iron aggregates; Prussian blue stain", "Denatured/precipitated hemoglobin; crystal violet (supravital) stain", "DNA remnants; Wright-Giemsa stain", "RNA aggregates; methylene blue stain"]', 1, 'Heinz bodies = precipitated, denatured hemoglobin clumps attached to the RBC membrane. They are NOT visible on routine Wright-Giemsa stain; they require supravital stains (crystal violet, new methylene blue). Heinz bodies are then plucked out by splenic macrophages, creating bite cells.'),
    (v_topic_id, 'Which of the following is NOT a classic trigger of hemolysis in G6PD deficiency?', '["Primaquine (antimalarial)", "Dapsone", "Fava beans (favism)", "Amoxicillin"]', 3, 'G6PD hemolysis is triggered by oxidative stress: antimalarials (primaquine, chloroquine), dapsone (sulfone), sulfonamides, nitrofurantoin, fava beans, and infections. Amoxicillin (a penicillin) does NOT cause oxidative hemolysis and is safe in G6PD deficiency.'),
    (v_topic_id, 'Why does testing for G6PD enzyme activity immediately after an acute hemolytic episode give a falsely normal result?', '["The body rapidly regenerates G6PD", "The most G6PD-deficient (oldest) RBCs were destroyed during the crisis; the remaining cells are young reticulocytes with higher residual G6PD activity", "G6PD is released from lysed cells into the plasma", "Hemolysis does not affect enzyme testing"]', 1, 'Critical exam point: test G6PD activity 2-3 months after an episode, when the RBC population is normalized. Right after crisis, young reticulocytes (with normal G6PD) predominate, masking the deficiency.'),
    (v_topic_id, 'African-American men with G6PD deficiency have a milder form (G6PD A-) than Mediterranean men (G6PD Mediterranean). Why?', '["African variant has a different mode of inheritance", "G6PD A- enzyme is structurally unstable and loses activity in older RBCs, while new reticulocytes have near-normal activity. The Mediterranean variant has near-zero activity at all cell ages.", "African men eat fewer fava beans", "African variant affects a different metabolic pathway"]', 1, 'G6PD A- (common in Africa) has a mildly unstable enzyme that retains near-normal activity in young RBCs. As cells age, activity drops. Hemolysis is therefore self-limited (older cells lyse; new young cells survive). Mediterranean G6PD is severely deficient at all RBC ages.'),
    (v_topic_id, 'G6PD deficiency is the most common cause of neonatal jaundice in certain populations. Why is neonatal jaundice from G6PD particularly dangerous?', '["Unconjugated bilirubin crosses the blood-brain barrier in neonates, causing kernicterus (bilirubin encephalopathy)", "It causes direct liver damage", "Conjugated bilirubin accumulates and causes cholestasis", "It depletes iron stores"]', 0, 'Unconjugated (indirect) bilirubin is lipid-soluble and readily crosses the immature neonatal blood-brain barrier. It deposits in the basal ganglia (kernicterus), causing irreversible brain damage. Phototherapy (UV light isomerizes bilirubin to a water-soluble form) is the treatment.'),
    (v_topic_id, 'On peripheral blood smear in an acute G6PD hemolytic episode, which TWO characteristic cell types are seen?', '["Spherocytes and schistocytes", "Bite cells (blister cells) and ghost cells (cells with Heinz bodies removed)", "Target cells and ring sideroblasts", "Hypersegmented neutrophils and macro-ovalocytes"]', 1, 'Bite cells: RBCs with a semicircular piece removed where Heinz bodies were plucked out by splenic macrophages. Ghost cells: severely damaged RBCs with absent hemoglobin content after Heinz body removal.'),

    -- SICKLE CELL DISEASE (71-80)
    (v_topic_id, 'Sickle cell disease is caused by a single point mutation in the beta-globin gene (Glu6Val). Under what conditions does HbS polymerize?', '["High oxygen tension, alkalosis, and hydration", "Low oxygen tension, acidosis, dehydration, and cold — all promoting HbS polymerization into rigid rods", "High altitude only", "High CO2 tension only"]', 1, 'Deoxygenated HbS changes shape, exposing a hydrophobic valine residue that interacts with adjacent HbS molecules, forming rigid polymer rods that distort the RBC into a sickle shape. Acidosis and dehydration promote sickling.'),
    (v_topic_id, 'Why does sickle cell disease not cause problems in the first 6 months of life?', '["The spleen filters sickled cells before they cause damage", "HbF (alpha2/gamma2) predominates at birth and does not polymerize with HbS, protecting against sickling until HbF production declines", "Maternal IgG antibodies neutralize sickled cells", "Neonatal RBCs are larger and more flexible"]', 1, 'HbF does not interact with HbS in polymerization. As gamma chain production falls (after 6 months) and beta chain production rises, HbS accumulates and sickling begins. This is why neonatal hemoglobin electrophoresis screening is critical.'),
    (v_topic_id, 'Hydroxyurea is the main disease-modifying therapy for sickle cell disease. What is its mechanism?', '["It chelates iron, preventing polymerization", "It inhibits ribonucleotide reductase, reducing cell division and increasing HbF production (gamma chain induction)", "It directly prevents HbS polymer formation", "It kills the most sickled RBCs selectively"]', 1, 'Hydroxyurea induces HbF production (mechanism not fully understood, but involves ribonucleotide reductase inhibition). HbF dilutes HbS and prevents polymerization. It also reduces WBC count (fewer WBC-mediated vascular occlusions) and RBC dehydration.'),
    (v_topic_id, 'A 5-year-old child with sickle cell disease develops sudden left-sided weakness. What is the most likely cause?', '["Septic embolism from bacteremia", "Ischemic stroke from sickle cell vaso-occlusion in cerebral arteries", "Intracranial hemorrhage", "TTP"]', 1, 'Sickle cell disease causes ischemic stroke in children (20-25% lifetime risk without prophylaxis). Sickled cells occlude cerebral arteries, particularly the internal carotid and middle cerebral artery territories. Transcranial Doppler screening and chronic transfusion therapy are used to prevent stroke.'),
    (v_topic_id, 'Which organism is the most common cause of life-threatening infection in children with sickle cell disease?', '["Staphylococcus aureus", "Streptococcus pneumoniae (pneumococcus)", "E. coli", "Haemophilus influenzae type b"]', 1, 'Functional asplenia (repeated splenic infarcts destroy the spleen by age 5) leaves sickle cell patients vulnerable to encapsulated bacteria, especially S. pneumoniae. Prophylactic penicillin (until age 5) and pneumococcal vaccination are mandatory.'),
    (v_topic_id, 'What is the most common cause of osteomyelitis in sickle cell disease?', '["Staphylococcus aureus", "Salmonella species (particularly typhimurium)", "Streptococcus pneumoniae", "E. coli"]', 1, 'While S. aureus is the most common cause of osteomyelitis in the general population, Salmonella is classically associated with SCD. Bone infarcts (from vaso-occlusion) create an ideal environment for Salmonella seeding. Both organisms must be covered empirically.'),
    (v_topic_id, 'Acute chest syndrome in sickle cell disease is defined by?', '["Severe chest pain without radiological changes", "New pulmonary infiltrate on CXR with chest pain, fever, and hypoxia — the leading cause of death in SCD adults", "Pleural effusion from splenic infarction", "Tension pneumothorax"]', 1, 'Acute chest syndrome is triggered by fat embolism (from infarcted bone marrow), pulmonary vaso-occlusion, or infection. It presents like pneumonia/PE and is the leading cause of death in adults with SCD. Treatment: exchange transfusion, O2, antibiotics, incentive spirometry.'),
    (v_topic_id, 'Dactylitis (hand-foot syndrome) is typically the FIRST clinical presentation of sickle cell disease. What is the underlying pathology?', '["Iron overload depositing in the small bones", "Vaso-occlusion and infarction of the small bones of the hands and feet in infants, causing painful swelling", "Avascular necrosis of the femoral head", "Osteomyelitis of the metacarpals"]', 1, 'Dactylitis occurs in infants (6 months to 2 years) when the bone marrow of hands and feet is still active. Sickled cells occlude the nutrient arteries, causing bone infarction and painful soft tissue swelling of the dorsum of the hands and feet.'),
    (v_topic_id, 'What is the characteristic finding in the spleen of an adult with longstanding sickle cell disease?', '["Massive congestive splenomegaly", "Autosplenectomy: a small, fibrotic, calcified spleen from repeated infarctions", "Normal spleen size", "Splenic lymphoma"]', 1, 'Repeated splenic infarctions (from vaso-occlusion) progressively destroy and fibrosis the spleen. By age 5, most SCD patients have functional asplenia. The spleen shrinks to a small calcified remnant -- autosplenectomy. This is the basis for the severe infection risk.'),
    (v_topic_id, 'Avascular necrosis (AVN) most commonly affects which bone in sickle cell disease?', '["Tibia", "Femoral head (osteonecrosis of the hip) and humeral head", "Vertebral bodies", "Skull"]', 1, 'The femoral and humeral heads have tenuous blood supplies via end arteries with no collaterals. Vaso-occlusion by sickled cells infarcts the bone, causing AVN. Patients present with progressive hip or shoulder pain. Joint replacement is ultimately required.'),
    (v_topic_id, 'Priapism is a painful complication of sickle cell disease. What is the pathophysiology?', '["Increased testosterone from testicular infarction", "Vaso-occlusion by sickled cells in the corpus cavernosum causes blood to stagnate, creating a low-flow (ischemic) priapism requiring urgent treatment", "Autonomic dysfunction from spinal cord infarction", "Elevated EPO causing increased blood viscosity"]', 1, 'Sickled RBCs occlude venous outflow from the corpora cavernosa. The trapped blood deoxygenates further, causing more sickling — a vicious cycle. Untreated ischemic priapism causes permanent erectile dysfunction. Treatment: aspiration, phenylephrine injection, exchange transfusion.')

    ON CONFLICT DO NOTHING;

END $$;

COMMIT;
